INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM231WRT1', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A nutritionist recommends that a client consume at least 50 grams of protein but no more than 2,000 calories per day. Each serving of chicken provides 25 grams of protein and 300 calories. Each serving of tofu provides 10 grams of protein and 150 calories. If the client eats $c$ servings of chicken and $t$ servings of tofu, which system of inequalities represents these nutritional constraints?', NULL, $lyceon_json$[{"key":"A","text":"$25c + 10t \\leq 50$ and $300c + 150t \\leq 2{,}000$"},{"key":"B","text":"$25c + 10t \\geq 50$ and $300c + 150t \\leq 2{,}000$"},{"key":"C","text":"$25c + 10t \\geq 50$ and $300c + 150t \\geq 2{,}000$"},{"key":"D","text":"$10c + 25t \\geq 50$ and $150c + 300t \\leq 2{,}000$"}]$lyceon_json$::jsonb, 'B', NULL, E'The client needs at least 50 grams of protein, so the protein inequality is $25c + 10t \\geq 50$, and the calorie limit of no more than 2,000 gives $300c + 150t \\leq 2{,}000$. The first option reverses the protein inequality to $\\leq 50$, which would cap protein intake rather than establishing a minimum. The third option reverses the calorie inequality to $\\geq 2{,}000$, which would require at least 2,000 calories rather than limiting them. The fourth option swaps the coefficients for chicken and tofu in both inequalities, assigning 10 grams of protein per serving of chicken instead of 25 and 25 grams per serving of tofu instead of 10.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2390NWN', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'What are the solutions to $\\sqrt{3x + 7} = x + 1$?', NULL, $lyceon_json$[{"key":"A","text":"$x = -2$ only"},{"key":"B","text":"$x = 3$ only"},{"key":"C","text":"$x = -2$ and $x = 3$"},{"key":"D","text":"$x = 6$ only"}]$lyceon_json$::jsonb, 'B', NULL, E'Squaring both sides: $3x + 7 = (x + 1)^2 = x^2 + 2x + 1$, which gives $x^2 - x - 6 = 0$, or $(x - 3)(x + 2) = 0$. The candidates are $x = 3$ and $x = -2$. Checking $x = 3$: $\\sqrt{3(3) + 7} = \\sqrt{16} = 4$ and $3 + 1 = 4$, so this is valid. Checking $x = -2$: $\\sqrt{3(-2) + 7} = \\sqrt{1} = 1$ and $-2 + 1 = -1$, so $1 \\neq -1$ and this is extraneous. Only $x = 3$ is valid. The distractor $x = -2$ only selects the extraneous solution while discarding the valid one. The distractor listing both values fails to check for extraneous solutions introduced by squaring. The distractor $x = 6$ results from an arithmetic slip when factoring the quadratic.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23COSHF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'grid_in', E'In a right triangle, one leg measures \\(5\\) and the hypotenuse measures \\(13\\). What is the length of the other leg?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '12', ARRAY['12'], E'Using the Pythagorean theorem \\(a^2 + b^2 = c^2\\) with \\(a = 5\\) and \\(c = 13\\): \\(25 + b^2 = 169\\), so \\(b^2 = 144\\), giving \\(b = 12\\). A common error is computing \\(\\sqrt{5^2 + 13^2} = \\sqrt{194}\\), treating both given values as legs rather than recognizing that 13 is the hypotenuse. Another error is computing \\(13 - 5 = 8\\), subtracting linearly instead of using squares.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM244XLT9', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'grid_in', E'The expression $\\frac{x^2 + 7x + 12}{x^2 - 9}$ can be rewritten as $\\frac{x + a}{x - b}$, where $a$ and $b$ are positive integers. What is the value of $a + b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Factor the numerator: $x^2 + 7x + 12 = (x + 3)(x + 4)$. Factor the denominator using the difference of squares: $x^2 - 9 = (x + 3)(x - 3)$. Cancel the common factor $(x + 3)$: $\\frac{(x + 3)(x + 4)}{(x + 3)(x - 3)} = \\frac{x + 4}{x - 3}$. Therefore $a = 4$ and $b = 3$, giving $a + b = 7$. A common error is factoring the numerator as $(x + 2)(x + 6)$, which would yield an incorrect sum. Another error is factoring the denominator as $(x - 3)^2$, neglecting that $x^2 - 9$ has two distinct factors.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM249QSZS', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'grid_in', E'A basketball player''s total points scored, y, after x games played this season is modeled by the equation y = 18.4x + 5.2. According to the model, how many more points does the player score, on average, for each additional game played?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '18.4', ARRAY['92/5', '18.4'], E'In the linear model y = 18.4x + 5.2, the slope is 18.4, which represents the average change in total points for each additional game played. Therefore, the player scores 18.4 more points, on average, per game. A common error is reporting the y-intercept (5.2) instead of the slope, confusing the initial value with the rate of change.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24BK5I0', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A hot-air balloon is at an altitude of $600$ feet and descends at a constant rate. The altitude $f(t)$, in feet, after $t$ minutes is modeled by $f(t) = -25t + 600$. After how many minutes will the balloon reach an altitude of $150$ feet?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$18$"},{"key":"C","text":"$24$"},{"key":"D","text":"$30$"}]$lyceon_json$::jsonb, 'B', NULL, E'Set the function equal to $150$: $-25t + 600 = 150$. Subtract $600$ from both sides: $-25t = -450$. Divide by $-25$: $t = 18$ minutes. The value $6$ results from dividing $150$ by $25$ without accounting for the initial altitude of $600$ feet. The value $24$ comes from solving $-25t + 600 = 0$, which finds when the balloon reaches the ground rather than $150$ feet. The value $30$ results from adding $150$ and $600$ to get $750$ and dividing by $25$, a sign error that treats the descent as if the target altitude is added to the starting altitude.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24RP5YO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A company randomly assigns $120$ employees to either a standing-desk group or a traditional-desk group to study the effect on daily productivity scores. After $8$ weeks, the standing-desk group has a significantly higher mean productivity score than the traditional-desk group. Which of the following conclusions is best supported by the design of this study?', NULL, $lyceon_json$[{"key":"A","text":"Standing desks cause higher productivity scores among all office workers."},{"key":"B","text":"Standing desks cause higher productivity scores among the employees in this company."},{"key":"C","text":"There is an association between desk type and productivity scores among the employees in this company, but causation cannot be established."},{"key":"D","text":"The results can be generalized to all companies that use standing desks."}]$lyceon_json$::jsonb, 'B', NULL, E'Because the study uses random assignment of treatments (standing desk vs. traditional desk) to the $120$ employees, it is a randomized experiment, which can support a causal conclusion. However, the participants are employees at one specific company, not a random sample of all office workers, so the causal conclusion applies only to this company''s employees. The claim that standing desks cause higher productivity among all office workers overgeneralizes beyond the study population. The claim that only an association can be established incorrectly denies the causal inference that random assignment permits. The claim that results generalize to all companies ignores that the sample was drawn from a single company.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24TABVH', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the positive value of $x$ that satisfies $|2x - 5| = 9$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'The absolute value equation $|2x - 5| = 9$ splits into two cases. Case 1: $2x - 5 = 9$, so $2x = 14$ and $x = 7$. Case 2: $2x - 5 = -9$, so $2x = -4$ and $x = -2$. The positive value is $7$. A common error is solving only the first case and not verifying it is positive, or solving the second case and reporting $-2$ without recognizing the question asks for the positive solution.', NULL, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25OX9XO', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A right circular cylinder with radius \\(3\\) and height \\(6\\) has a hemisphere of radius \\(3\\) removed from one of its flat faces. What is the volume of the remaining solid?', NULL, $lyceon_json$[{"key":"A","text":"\\(36\\pi\\)"},{"key":"B","text":"\\(54\\pi\\)"},{"key":"C","text":"\\(18\\pi\\)"},{"key":"D","text":"\\(72\\pi\\)"}]$lyceon_json$::jsonb, 'A', NULL, E'The cylinder volume is \\(\\pi r^2 h = \\pi(9)(6) = 54\\pi\\). The hemisphere volume is \\(\\frac{2}{3}\\pi r^3 = \\frac{2}{3}\\pi(27) = 18\\pi\\). The remaining solid has volume \\(54\\pi - 18\\pi = 36\\pi\\). The value \\(54\\pi\\) is the full cylinder volume without removing the hemisphere. The value \\(18\\pi\\) equals only the hemisphere volume, as if the hemisphere itself were the answer rather than the portion subtracted from the cylinder. The value \\(72\\pi\\) results from adding the cylinder and hemisphere volumes instead of subtracting.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25ZF1JO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'The annual salaries, in thousands of dollars, of 7 employees at a small company are: 42, 45, 48, 48, 52, 55, 60. What is the median salary, in thousands of dollars?', NULL, $lyceon_json$[{"key":"A","text":"45"},{"key":"B","text":"48"},{"key":"C","text":"50"},{"key":"D","text":"52"}]$lyceon_json$::jsonb, 'B', NULL, E'With 7 values in ascending order, the median is the 4th value. The ordered data is 42, 45, 48, 48, 52, 55, 60, and the 4th value is 48. The distractor 45 results from incorrectly selecting the 2nd value, confusing the position of the middle value. The distractor 50 results from averaging the 3rd and 5th values (48 and 52), applying the even-count median procedure to an odd-count data set. The distractor 52 results from selecting the 5th value, counting from the wrong end of the sorted list.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 35, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2675UXA', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A pool maintenance company charges a monthly fee of $\\$50$ plus $\\$12$ per service visit. The total monthly cost, in dollars, as a function of the number of visits $v$ is modeled by $f(v) = 12v + 50$. What does the number $12$ represent in this function?', NULL, $lyceon_json$[{"key":"A","text":"The total monthly cost for all visits"},{"key":"B","text":"The number of service visits per month"},{"key":"C","text":"The cost, in dollars, per service visit"},{"key":"D","text":"The fixed monthly fee regardless of visits"}]$lyceon_json$::jsonb, 'C', NULL, E'In the function $f(v) = 12v + 50$, the coefficient $12$ multiplies the number of visits $v$, so it represents the cost per service visit. The total monthly cost for all visits is not a single constant but depends on how many visits occur, so that interpretation is incorrect. The number of visits per month is the input variable $v$, not the coefficient $12$. The fixed monthly fee regardless of visits is the constant term $50$, not $12$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26FONQZ', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'A water treatment plant processes water at a constant rate. At 8:00 AM, the plant has processed a total of $2{,}400$ gallons. By 11:00 AM, it has processed a total of $4{,}500$ gallons. If the plant began processing at 6:00 AM, how many gallons had been processed by 6:00 AM?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '1000', ARRAY['1000'], E'The rate of processing is $\\frac{4{,}500 - 2{,}400}{11 - 8} = \\frac{2{,}100}{3} = 700$ gallons per hour. Since 8:00 AM is $2$ hours after 6:00 AM, the total processed at 6:00 AM is $2{,}400 - 2(700) = 2{,}400 - 1{,}400 = 1{,}000$ gallons. One common error is computing the rate incorrectly by dividing the total at 11:00 AM by the number of hours ($4{,}500 \\div 3 = 1{,}500$), which gives an incorrect rate. Another error is subtracting only one hour of processing instead of two, yielding $2{,}400 - 700 = 1{,}700$.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28E736P', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'An investor divides $\\$10{,}000$ between two accounts. Account X earns $4\\%$ annual simple interest, and Account Y earns $6\\%$ annual simple interest. If the total interest earned after one year is $\\$480$, how many dollars were invested in Account X?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6000', ARRAY['6000'], E'Let $x$ be the amount in Account X and $y$ be the amount in Account Y. The system is $x + y = 10{,}000$ and $0.04x + 0.06y = 480$. Substituting $y = 10{,}000 - x$ gives $0.04x + 0.06(10{,}000 - x) = 480$, which simplifies to $0.04x + 600 - 0.06x = 480$, then $-0.02x = -120$, so $x = 6{,}000$. A common error is solving for Account Y ($y = 4{,}000$) and reporting that instead. Another error is setting up the interest equation with the rates swapped, assigning $6\\%$ to Account X and $4\\%$ to Account Y, which yields $x = 4{,}000$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B43C47', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two independent random samples are taken to estimate the proportion of residents in a city who support a new public transit plan. Sample 1 surveys 500 residents and finds 52% support, with a margin of error of 4.4 percentage points. Sample 2 surveys 1{,}200 residents and finds 46% support, with a margin of error of 2.8 percentage points. Based on these confidence intervals, which of the following conclusions is most justified?', NULL, $lyceon_json$[{"key":"A","text":"A majority of all city residents support the plan, because Sample 1 found more than 50% support."},{"key":"B","text":"Fewer than half of all city residents support the plan, because Sample 2 has a larger sample size and is therefore more reliable."},{"key":"C","text":"The confidence intervals overlap, so the data do not provide strong evidence that the true proportion differs between the two samples."},{"key":"D","text":"The true proportion of residents who support the plan is exactly 49%, the average of the two sample proportions."}]$lyceon_json$::jsonb, 'C', NULL, E'Sample 1 gives a confidence interval of (47.6%, 56.4%) and Sample 2 gives (43.2%, 48.8%). These intervals overlap in the range (47.6%, 48.8%), so the data do not provide strong evidence that the true population proportion is different between the two estimates. The conclusion that a majority supports the plan relies only on Sample 1 while ignoring Sample 2''s contradictory result. The conclusion favoring Sample 2 solely because of its larger size ignores that the intervals overlap. Averaging the two sample proportions to obtain an exact value misrepresents how confidence intervals work and treats an estimate as a precise parameter.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C1102R', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ has the equation $3x - 9y = 27$. Line $q$ is perpendicular to line $p$ and passes through the point $(6, -1)$. What is the equation of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$y = -3x + 17$"},{"key":"B","text":"$y = 3x - 19$"},{"key":"C","text":"$y = -3x + 19$"},{"key":"D","text":"$y = \\frac{1}{3}x - 3$"}]$lyceon_json$::jsonb, 'A', NULL, E'First, rewrite line $p$ in slope-intercept form: $3x - 9y = 27$ becomes $-9y = -3x + 27$, so $y = \\frac{1}{3}x - 3$. The slope of line $p$ is $\\frac{1}{3}$. A line perpendicular to line $p$ has slope $-3$ (the negative reciprocal). Using point-slope form with $(6, -1)$: $y - (-1) = -3(x - 6)$, which gives $y + 1 = -3x + 18$, so $y = -3x + 17$. The equation $y = 3x - 19$ results from using the reciprocal $3$ without negating, a sign error. The equation $y = -3x + 19$ uses the correct slope but makes an arithmetic error when simplifying $y + 1 = -3x + 18$, adding $1$ instead of subtracting it. The equation $y = \\frac{1}{3}x - 3$ is simply line $p$ itself, reflecting a failure to find the perpendicular slope.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C3CTRX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'grid_in', E'A recipe calls for \\frac{3}{4} cup of flour to make 12 cookies. How many cups of flour are needed to make 48 cookies?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'Since 48 cookies is 4 times 12 cookies, the flour needed is 4 \\times \\frac{3}{4} = 3 cups. The scaling factor is \\frac{48}{12} = 4, applied directly to the flour quantity.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CTFGV0', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'A rectangular box has dimensions \\(3\\), \\(4\\), and \\(12\\). What is the length of the space diagonal of the box?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13', ARRAY['13'], E'The space diagonal \\(d\\) of a rectangular box with dimensions \\(a\\), \\(b\\), and \\(c\\) is \\(d = \\sqrt{a^2 + b^2 + c^2}\\). Substituting: \\(d = \\sqrt{9 + 16 + 144} = \\sqrt{169} = 13\\). A common error is computing only a face diagonal, such as \\(\\sqrt{3^2 + 4^2} = 5\\), and reporting that as the answer. Another error is finding a different face diagonal like \\(\\sqrt{4^2 + 12^2} = \\sqrt{160}\\) without incorporating the third dimension.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DE2UP2', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f$ is defined by $$f(x) = \\begin{cases} 2x + 1 & \\text{if } x < 0 \\\\ x^2 - 3 & \\text{if } x \\geq 0 \\end{cases}$$ What is the value of $f(3)$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$7$"},{"key":"C","text":"$-3$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'A', NULL, E'Since $3 \\geq 0$, the second piece of the function applies: $f(3) = 3^2 - 3 = 9 - 3 = 6$. The distractor $7$ results from using the wrong piece of the function, computing $2(3) + 1 = 7$, which applies only when $x < 0$. The distractor $-3$ comes from substituting $x = 0$ instead of $x = 3$ into the second piece, yielding $0^2 - 3 = -3$. The distractor $12$ results from computing $3^2 + 3 = 12$, a sign error in the constant term.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 35, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DNZMCF', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'What is the value of $x$ in the equation $\\frac{4x - 3}{6} + \\frac{x + 9}{3} = 5$?', NULL, $lyceon_json$[{"key":"A","text":"$1.5$"},{"key":"B","text":"$2.5$"},{"key":"C","text":"$3$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'B', NULL, E'Multiply every term by the least common denominator $6$: $(4x - 3) + 2(x + 9) = 30$. Distribute: $4x - 3 + 2x + 18 = 30$. Combine like terms: $6x + 15 = 30$. Subtract $15$: $6x = 15$, so $x = 2.5$. The value $1.5$ results from a sign error, treating $-3$ in the numerator as $+3$, which gives $6x + 21 = 30$ and $x = 1.5$. The value $3$ comes from failing to distribute the $2$ to the $x$ term in $2(x + 9)$, computing $4x - 3 + x + 18 = 30$, which yields $5x = 15$ and $x = 3$. The value $4$ results from failing to distribute the $2$ to the $9$ in $2(x + 9)$, computing $4x - 3 + 2x + 9 = 30$, which gives $6x + 6 = 30$ and $x = 4$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EO5SNU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A paint store mixes custom colors using red, blue, and white paint in the ratio 3:5:2 by volume. A customer orders 8 gallons of the custom color but then asks to increase the proportion of blue by adding extra blue paint so that the new ratio becomes 3:7:2. How many total gallons of paint are in the modified mixture?', NULL, $lyceon_json$[{"key":"A","text":"9.2"},{"key":"B","text":"9.6"},{"key":"C","text":"10.0"},{"key":"D","text":"10.4"}]$lyceon_json$::jsonb, 'B', NULL, E'In the original ratio 3:5:2, the total is 10 parts. For 8 gallons, each part is \\frac{8}{10} = 0.8 gallons. Red = 2.4 gallons, blue = 4.0 gallons, white = 1.6 gallons. To achieve ratio 3:7:2 while keeping red and white the same, the new blue amount is 7 \\times 0.8 = 5.6 gallons. Total = 2.4 + 5.6 + 1.6 = 9.6 gallons. The distractor 9.2 results from computing blue as 6 parts instead of 7, adding only 0.8 gallons of blue instead of 1.6. The distractor 10.0 comes from incorrectly rescaling all three components to the new 12-part ratio with the same 8-gallon total, then adding the extra blue separately. The distractor 10.4 results from computing blue as 8 parts instead of 7, giving blue = 6.4 gallons and total = 2.4 + 6.4 + 1.6 = 10.4.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F3UGM1', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'A factory can produce at most 200 widgets per day. If the factory has already produced 75 widgets today, which inequality represents the number of additional widgets, $w$, the factory can still produce today?', NULL, $lyceon_json$[{"key":"A","text":"$w \\leq 125$"},{"key":"B","text":"$w \\geq 125$"},{"key":"C","text":"$w \\leq 275$"},{"key":"D","text":"$w < 125$"}]$lyceon_json$::jsonb, 'A', NULL, E'The factory can produce at most 200 widgets total, and 75 have already been produced, so the remaining production satisfies $75 + w \\leq 200$, which simplifies to $w \\leq 125$. The option $w \\geq 125$ reverses the inequality direction, requiring at least 125 more widgets rather than allowing up to 125. The option $w \\leq 275$ results from incorrectly adding 75 to 200 instead of subtracting, setting up the constraint as $w \\leq 200 + 75$. The option $w < 125$ uses a strict inequality, which would exclude exactly 125 additional widgets; since "at most 200" means $\\leq 200$, producing exactly 125 more (reaching 200 total) is permitted, so the boundary must be inclusive.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F799NX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'grid_in', E'At a high school, 90 students belong to the art club, the debate club, or both. Of these students, 54 belong to the art club and 60 belong to the debate club. If a student is selected at random from those who belong to the art club, what is the probability that this student also belongs to the debate club? Express your answer as a fraction.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4/9', ARRAY['4/9', '0.444', '.444'], E'By the inclusion-exclusion principle, the number of students in both clubs is 54 + 60 - 90 = 24. Given that a student is in the art club (54 students), the conditional probability that this student is also in the debate club is \\frac{24}{54} = \\frac{4}{9}. A common error is dividing by the total 90 instead of conditioning on art club membership, yielding \\frac{24}{90}. Another error is dividing by 60 (the debate club total) instead of 54. Forgetting to use inclusion-exclusion and using 60 as the overlap count would also produce an incorrect answer.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FSRRWF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A farmer records the amount of fertilizer used (in pounds) and the crop yield (in bushels) for several fields. The line of best fit for the data is y = 2.5x + 30, where x is the pounds of fertilizer and y is the crop yield in bushels. According to this model, what is the predicted crop yield for a field that uses 20 pounds of fertilizer?', NULL, $lyceon_json$[{"key":"A","text":"50 bushels"},{"key":"B","text":"55 bushels"},{"key":"C","text":"75 bushels"},{"key":"D","text":"80 bushels"}]$lyceon_json$::jsonb, 'D', NULL, E'Substituting x = 20: y = 2.5(20) + 30 = 50 + 30 = 80 bushels. The distractor 50 bushels comes from computing only the product 2.5 \\times 20 without adding the y-intercept. The distractor 55 bushels results from a slope error such as using 1.25 instead of 2.5, giving 1.25(20) + 30 = 55. The distractor 75 bushels comes from an arithmetic error such as computing 2.5 \\times 18 + 30 = 75.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G1KDCJ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'If $4^{x+1} = 8^{2x-1}$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5/4', ARRAY['5/4', '1.25'], E'Rewrite both sides with base $2$: $4^{x+1} = (2^2)^{x+1} = 2^{2(x+1)} = 2^{2x+2}$ and $8^{2x-1} = (2^3)^{2x-1} = 2^{3(2x-1)} = 2^{6x-3}$. Setting the exponents equal: $2x + 2 = 6x - 3$, so $5 = 4x$ and $x = \\frac{5}{4}$. A common error is failing to convert both bases to the same prime base. Another error is incorrectly distributing the exponent, for instance writing $2^{2x+1}$ instead of $2^{2x+2}$ for the left side, which leads to a different answer.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GBQCWN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A hospital conducted a study in which patients who chose to take a daily vitamin supplement were compared to patients who chose not to take the supplement. After one year, the supplement group had a lower rate of respiratory infections. A health magazine reported that taking the vitamin supplement reduces respiratory infections. Which of the following is the most significant flaw in the magazine''s conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The study did not include a placebo group."},{"key":"B","text":"Because patients chose whether to take the supplement, the groups may differ in health-conscious behaviors that also affect infection rates, so a causal conclusion is not justified."},{"key":"C","text":"The study lasted only one year, which is too short to draw any conclusions."},{"key":"D","text":"The sample size of the study was not reported in the magazine article."}]$lyceon_json$::jsonb, 'B', NULL, E'The most significant flaw is that this is an observational study, not an experiment: patients self-selected into groups. People who choose to take supplements may also exercise more, eat healthier, or engage in other behaviors that reduce infection risk. These confounding variables make it impossible to attribute the lower infection rate to the supplement alone. While the absence of a placebo group is a limitation, the fundamental problem is the lack of random assignment, not just the absence of a placebo. The one-year duration, though potentially a concern, does not address the core issue of confounding. The unreported sample size is a reporting deficiency but does not explain why the causal claim is unjustified.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 95, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GQIBZ8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A circular walking path lies between two concentric circles. The outer circle has a radius of \\(10\\) feet and the inner circle has a radius of \\(8\\) feet. What is the area of the walking path, in square feet?', NULL, $lyceon_json$[{"key":"A","text":"\\(2\\pi\\)"},{"key":"B","text":"\\(4\\pi\\)"},{"key":"C","text":"\\(36\\pi\\)"},{"key":"D","text":"\\(64\\pi\\)"}]$lyceon_json$::jsonb, 'C', NULL, E'The area of the annular region is the difference of the areas of the two circles: \\(\\pi(10^2) - \\pi(8^2) = 100\\pi - 64\\pi = 36\\pi\\) square feet. The value \\(2\\pi\\) results from computing \\(\\pi(10 - 8)\\), using the difference of radii times \\(\\pi\\) instead of the difference of squared radii. The value \\(4\\pi\\) results from computing \\(\\pi(10 - 8)^2\\), squaring the difference of radii instead of subtracting the squares. The value \\(64\\pi\\) uses only the inner circle area, ignoring the subtraction entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H1ZW3L', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'The median home price in a city was $\\$250{,}000$ in 2022. In 2023, the median home price increased by $20\\%$. In 2024, the median home price decreased by $10\\%$ from the 2023 price. What is the median home price, in thousands of dollars, in 2024?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '270', ARRAY['270'], E'The 2023 price is $250{,}000 \\times 1.20 = 300{,}000$. The 2024 price is $300{,}000 \\times 0.90 = 270{,}000$. In thousands of dollars, this is $270$. A common error is computing the net change as $20\\% - 10\\% = 10\\%$ and applying it to the original price, yielding $250 \\times 1.10 = 275$ thousand. This ignores that the $10\\%$ decrease applies to the larger 2023 price, not the original 2022 price. Another error is computing $250 \\times 0.20 \\times 0.10 = 5$ and subtracting from $250$ to get $245$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H91RHV', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle \\(PQR\\), point \\(M\\) is the midpoint of \\(\\overline{PQ}\\) and point \\(N\\) is the midpoint of \\(\\overline{PR}\\). If \\(QR = 18\\), what is the length of \\(\\overline{MN}\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\(6\\)"},{"key":"B","text":"\\(9\\)"},{"key":"C","text":"\\(12\\)"},{"key":"D","text":"\\(18\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'By the triangle midsegment theorem, the segment connecting the midpoints of two sides of a triangle is parallel to the third side and half its length. Since \\(QR = 18\\), the midsegment \\(MN = \\frac{18}{2} = 9\\). The value \\(6\\) results from dividing by 3 instead of 2, confusing this with a centroid ratio. The value \\(12\\) results from computing \\(\\frac{2}{3}\\) of 18, applying the centroid division rather than the midsegment theorem. The value \\(18\\) results from assuming the midsegment equals the full third side.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HJH0CQ', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the value of $x$ in the equation $7(x - 3) + 2 = 5x + 9$?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$5$"},{"key":"C","text":"$14$"},{"key":"D","text":"$-14$"}]$lyceon_json$::jsonb, 'C', NULL, E'Distribute $7$ across the parentheses: $7x - 21 + 2 = 5x + 9$. Combine like terms on the left: $7x - 19 = 5x + 9$. Subtract $5x$ from both sides: $2x - 19 = 9$. Add $19$ to both sides: $2x = 28$, so $x = 14$. The value $5$ results from failing to multiply $-3$ by $7$ during distribution, treating $7(x - 3)$ as $7x - 3$. The value $2$ results from incorrectly distributing the negative sign and computing $7(x - 3)$ as $7x + 3$, which leads to $7x + 5 = 5x + 9$ and then $x = 2$. The value $-14$ results from a sign error when collecting variable terms, obtaining $2x = -28$ instead of $2x = 28$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I74KKW', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cone has a base radius of \\(3\\) and a height of \\(9\\). The top of the cone is removed by a cut parallel to the base at a height of \\(6\\) from the base, creating a frustum. What is the volume of the frustum?', NULL, $lyceon_json$[{"key":"A","text":"\\(23\\pi\\)"},{"key":"B","text":"\\(26\\pi\\)"},{"key":"C","text":"\\(27\\pi\\)"},{"key":"D","text":"\\(78\\pi\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'The original cone has radius \\(3\\) and height \\(9\\), so its volume is \\(\\frac{1}{3}\\pi(3^2)(9) = 27\\pi\\). The cut at height \\(6\\) from the base removes a smaller cone from the top with height \\(9 - 6 = 3\\). By similar triangles, the small cone''s radius is \\(\\frac{3}{9} \\cdot 3 = 1\\). The volume of the small cone is \\(\\frac{1}{3}\\pi(1^2)(3) = \\pi\\). The frustum volume is \\(27\\pi - \\pi = 26\\pi\\). The value \\(23\\pi\\) results from using an incorrect small-cone radius of \\(2\\) (applying the height ratio to the wrong dimension), giving a removed volume of \\(\\frac{1}{3}\\pi(4)(3) = 4\\pi\\) and a frustum of \\(23\\pi\\). The value \\(27\\pi\\) is the full cone volume without subtracting the removed portion. The value \\(78\\pi\\) results from using the frustum formula without the \\(\\frac{1}{3}\\) factor: \\(\\pi(6)(9 + 3 + 1) = 78\\pi\\).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I8BT3L', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which of the following is equivalent to $\\frac{2}{x - 1} + \\frac{3}{x + 2}$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{5}{2x + 1}$"},{"key":"B","text":"$\\frac{5x + 7}{x^2 + x - 2}$"},{"key":"C","text":"$\\frac{5x + 1}{x^2 + x - 2}$"},{"key":"D","text":"$\\frac{5x + 5}{x^2 + x - 2}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The common denominator is $(x - 1)(x + 2) = x^2 + x - 2$. Rewriting each fraction: $\\frac{2(x + 2) + 3(x - 1)}{x^2 + x - 2} = \\frac{2x + 4 + 3x - 3}{x^2 + x - 2} = \\frac{5x + 1}{x^2 + x - 2}$. The distractor $\\frac{5}{2x + 1}$ results from adding both numerators and both denominators directly, a fundamental error in fraction addition. The distractor with numerator $5x + 7$ comes from a sign error when distributing $3(x - 1)$, computing $3x + 3$ instead of $3x - 3$. The distractor with numerator $5x + 5$ comes from an arithmetic slip, computing $4 + 1 = 5$ instead of the correct $4 - 3 = 1$ when combining the constant terms.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IK94XZ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In right triangle \\(ABC\\) with the right angle at \\(C\\), \\(\\sin(A) = \\frac{3}{5}\\). What is the value of \\(\\cos(A)\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\(\\frac{3}{5}\\)"},{"key":"B","text":"\\(\\frac{4}{5}\\)"},{"key":"C","text":"\\(\\frac{3}{4}\\)"},{"key":"D","text":"\\(\\frac{5}{3}\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'Since \\(\\sin(A) = \\frac{3}{5}\\), the side opposite angle \\(A\\) is 3 and the hypotenuse is 5. By the Pythagorean theorem, the adjacent side is \\(\\sqrt{25 - 9} = 4\\). Therefore \\(\\cos(A) = \\frac{4}{5}\\). The value \\(\\frac{3}{5}\\) confuses cosine with sine, assuming they are equal. The value \\(\\frac{3}{4}\\) computes the tangent (opposite over adjacent) instead of the cosine. The value \\(\\frac{5}{3}\\) computes the cosecant (reciprocal of sine) rather than the cosine.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J9XY0Q', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'Two parallel lines are cut by a transversal. One of the co-interior angles (same-side interior angles) measures \\((3x + 10)°\\) and the other measures \\((5x - 6)°\\). What is the value of \\(x\\)?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '22', ARRAY['22'], E'Co-interior angles formed by parallel lines cut by a transversal are supplementary, meaning they sum to \\(180°\\). Setting up the equation: \\((3x + 10) + (5x - 6) = 180\\). Combining like terms gives \\(8x + 4 = 180\\). Subtracting 4 from both sides: \\(8x = 176\\). Dividing by 8: \\(x = 22\\). A common error is setting the angles equal instead of supplementary (treating them as alternate interior angles), which gives \\(2x = 16\\) and \\(x = 8\\). Another error is sign mistakes when combining the constant terms \\(+10\\) and \\(-6\\).', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JJIRQS', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'A delivery truck travels from City A to City B, a total distance of 180 miles. On the highway, the truck averages 60 miles per hour, and on local roads, the truck averages 30 miles per hour. If the entire trip takes 4 hours, how many miles does the truck travel on the highway?', NULL, $lyceon_json$[{"key":"A","text":"$60$"},{"key":"B","text":"$90$"},{"key":"C","text":"$120$"},{"key":"D","text":"$150$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let $h$ be the highway miles and $l$ be the local road miles. The system is $h + l = 180$ and $\\frac{h}{60} + \\frac{l}{30} = 4$. Substituting $l = 180 - h$ into the time equation gives $\\frac{h}{60} + \\frac{180 - h}{30} = 4$, which simplifies to $\\frac{h}{60} + 6 - \\frac{h}{30} = 4$, then $-\\frac{h}{60} = -2$, so $h = 120$. The value 60 results from solving the system correctly but reporting the local road distance ($l = 60$) instead of the highway distance. The value 90 comes from incorrectly assuming equal distances on each road type. The value 150 results from assuming without calculation that local road travel takes exactly 1 hour, giving $l = 30$ and $h = 150$, which does not satisfy the time equation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K98MQZ', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'If $8x - 20 = 44$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'Add $20$ to both sides of the equation to get $8x = 64$. Then divide both sides by $8$ to find $x = 8$. A common error is subtracting $20$ from $44$ and then failing to divide, yielding $24$. Another error is dividing $44$ by $8$ first without adding $20$, yielding $5.5$.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L12MO6', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'grid_in', E'A weather service randomly selects 600 of its daily forecasts from the past year and finds that 78% were accurate. If the margin of error at the 95% confidence level is approximately \\frac{1}{\\sqrt{n}} for a sample of size n, what is the approximate margin of error, to the nearest hundredth?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '0.04', ARRAY['1/25', '0.04', '.04'], E'Using the given approximation, the margin of error is \\frac{1}{\\sqrt{600}}. Since \\sqrt{600} \\approx 24.49, this gives \\frac{1}{24.49} \\approx 0.0408, which rounds to 0.04 to the nearest hundredth. A common error is using n = 78 (the percentage) instead of n = 600 (the sample size). Another error is forgetting to take the square root and computing \\frac{1}{600}. Computing \\sqrt{600} incorrectly as 60 would yield \\frac{1}{60} \\approx 0.02.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N17SRG', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'A gardener plants roses and tulips in a garden bed that holds exactly 52 plants. Each rose requires 3 square feet of space and each tulip requires 2 square feet. If the garden bed has exactly 120 square feet of planting area and all of it is used, what is the value of $r - t$, where $r$ is the number of roses and $t$ is the number of tulips?', NULL, $lyceon_json$[{"key":"A","text":"$-20$"},{"key":"B","text":"$-4$"},{"key":"C","text":"$16$"},{"key":"D","text":"$20$"}]$lyceon_json$::jsonb, 'A', NULL, E'The system is $r + t = 52$ and $3r + 2t = 120$. Substituting $t = 52 - r$ into the second equation gives $3r + 2(52 - r) = 120$, so $3r + 104 - 2r = 120$, yielding $r = 16$. Then $t = 52 - 16 = 36$, and $r - t = 16 - 36 = -20$. The value $-4$ results from an arithmetic slip such as computing $16 - 20$ instead of $16 - 36$, likely from miscalculating $t$. The value $16$ comes from finding $r$ correctly but stopping there without computing $r - t$. The value $20$ comes from computing $t - r = 36 - 16 = 20$ instead of $r - t$, reversing the order of subtraction and dropping the negative sign.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NQO7WG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A restaurant offers 8 appetizers, 12 entrees, and 5 desserts on its menu. If a customer randomly selects one item from the entire menu, what is the probability that the item is an entree?', NULL, $lyceon_json$[{"key":"A","text":"\\frac{8}{25}"},{"key":"B","text":"\\frac{12}{25}"},{"key":"C","text":"\\frac{5}{25}"},{"key":"D","text":"\\frac{12}{20}"}]$lyceon_json$::jsonb, 'B', NULL, E'The total number of menu items is 8 + 12 + 5 = 25. The probability of selecting an entree is \\frac{12}{25}. The answer \\frac{8}{25} results from selecting the appetizer count instead of the entree count. The answer \\frac{5}{25} results from selecting the dessert count. The answer \\frac{12}{20} results from incorrectly calculating the total as 20 by omitting one category.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P4X5XR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A store offers a 20\\% discount on all electronics. After the discount, a customer applies a \\$30 coupon. Sales tax of 6\\% is then added to the amount after the coupon. If a television has an original price of \\$550, what is the total amount the customer pays?', NULL, $lyceon_json$[{"key":"A","text":"\\$434.60"},{"key":"B","text":"\\$436.40"},{"key":"C","text":"\\$440.96"},{"key":"D","text":"\\$466.40"}]$lyceon_json$::jsonb, 'A', NULL, E'After the 20\\% discount: 550 \\times 0.80 = 440. After the \\$30 coupon: 440 - 30 = 410. With 6\\% tax: 410 \\times 1.06 = 434.60. The distractor \\$436.40 results from applying the tax before the coupon: 440 \\times 1.06 = 466.40, then 466.40 - 30 = 436.40. The distractor \\$440.96 results from applying the coupon before the percentage discount: (550 - 30) \\times 0.80 \\times 1.06 = 520 \\times 0.80 \\times 1.06 = 416 \\times 1.06 = 440.96. The distractor \\$466.40 results from ignoring the coupon entirely and computing only the discount plus tax: 440 \\times 1.06 = 466.40.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P5D75U', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A traveler exchanges 500 US dollars for euros at a rate of 1 US dollar = 0.90 euros. After spending 200 euros, the traveler converts the remaining euros back to US dollars at a rate of 1 euro = 1.10 US dollars. How many US dollars does the traveler have after converting back?', NULL, $lyceon_json$[{"key":"A","text":"\\$275"},{"key":"B","text":"\\$278"},{"key":"C","text":"\\$300"},{"key":"D","text":"\\$330"}]$lyceon_json$::jsonb, 'A', NULL, E'The traveler receives 500 \\times 0.90 = 450 euros. After spending 200 euros, 450 - 200 = 250 euros remain. Converting back: 250 \\times 1.10 = \\$275. The distractor \\$278 results from dividing 250 by 0.90 instead of multiplying by 1.10, yielding approximately 277.78 rounded to 278. The distractor \\$300 comes from incorrectly subtracting the euro spending from the original dollar amount (500 - 200 = 300), mixing units. The distractor \\$330 results from computing 500 - 200 = 300 and then multiplying by the return rate (300 \\times 1.10 = 330), compounding the unit-mixing error with an extra conversion step.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"unit_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PJ57JJ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two parallel lines are cut by a transversal. One of the alternate interior angles measures \\(65°\\). What is the measure of the other alternate interior angle?', NULL, $lyceon_json$[{"key":"A","text":"\\(25°\\)"},{"key":"B","text":"\\(65°\\)"},{"key":"C","text":"\\(115°\\)"},{"key":"D","text":"\\(130°\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'When two parallel lines are cut by a transversal, alternate interior angles are congruent. Therefore the other alternate interior angle also measures \\(65°\\). The value \\(25°\\) comes from subtracting \\(65°\\) from \\(90°\\), confusing the relationship with complementary angles. The value \\(115°\\) comes from computing \\(180° - 65°\\), which gives the supplementary co-interior angle rather than the alternate interior angle. The value \\(130°\\) comes from doubling \\(65°\\), which has no geometric basis here.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QKZT74', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A medical screening test for a certain condition has a 95% true positive rate (it correctly identifies 95% of people who have the condition) and a 92% true negative rate (it correctly identifies 92% of people who do not have the condition). In a population of 10{,}000 people, 200 have the condition. If a person selected at random from this population tests positive, what is the probability that the person actually has the condition?', NULL, $lyceon_json$[{"key":"A","text":"\\frac{190}{974}"},{"key":"B","text":"\\frac{190}{784}"},{"key":"C","text":"\\frac{190}{200}"},{"key":"D","text":"\\frac{784}{974}"}]$lyceon_json$::jsonb, 'A', NULL, E'Of the 200 people with the condition, 0.95 \\times 200 = 190 test positive (true positives). Of the 9{,}800 without the condition, 0.08 \\times 9{,}800 = 784 test positive (false positives). The total number of positive tests is 190 + 784 = 974. The probability that a person who tests positive actually has the condition is \\frac{190}{974}. The answer \\frac{190}{784} incorrectly divides true positives by false positives only, omitting the true positives from the denominator. The answer \\frac{190}{200} gives the true positive rate itself rather than the predictive value. The answer \\frac{784}{974} gives the proportion of false positives among all positives, which is the complement of the correct answer.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QMXXIE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'Researchers want to determine whether a new organic pesticide reduces crop damage compared to the standard pesticide. They randomly assign 40 identical plots to receive either the new organic pesticide or the standard pesticide. At the end of the growing season, they compare the average crop damage between the two groups. This study is best described as', NULL, $lyceon_json$[{"key":"A","text":"a survey, because the researchers collected data from the plots."},{"key":"B","text":"an observational study, because the researchers observed crop damage."},{"key":"C","text":"an experiment, because the researchers randomly assigned treatments to plots."},{"key":"D","text":"a census, because the researchers examined all 40 plots."}]$lyceon_json$::jsonb, 'C', NULL, E'The study is an experiment because the researchers actively imposed a treatment (type of pesticide) by randomly assigning plots to groups. Random assignment of treatments is the defining feature of an experiment. Calling it a survey is incorrect because surveys collect self-reported information from respondents, not measurements on experimental units. Calling it an observational study is incorrect because the researchers controlled which treatment each plot received rather than merely observing existing conditions. Calling it a census is incorrect because a census attempts to measure every member of a population, which is not the design here.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RH51KL', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the slope of the line $4x - 2y = 10$?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$-2$"},{"key":"C","text":"$2$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'C', NULL, E'Rewrite the equation in slope-intercept form by isolating $y$: $-2y = -4x + 10$, so $y = 2x - 5$. The slope is $2$. The value $-5$ results from confusing the $y$-intercept with the slope. The value $-2$ comes from taking the coefficient of $y$ in the original equation without correctly solving for $y$, neglecting the sign change. The value $4$ results from reading the coefficient of $x$ in the original equation without dividing by the coefficient of $y$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RO7DNB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'The daily high temperatures, in degrees Fahrenheit, recorded over 10 days in a city are: 72, 75, 68, 71, 74, 79, 73, 70, 76, 72. What is the range of the daily high temperatures?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'The range is the maximum value minus the minimum value. The maximum temperature is 79 and the minimum is 68. The range is 79 - 68 = 11. A common error is misidentifying the minimum as 70 instead of 68 because the data is not presented in sorted order, which would give a range of 9.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SG8OB4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 400 customers at a shopping mall found that 68% were satisfied with the mall''s facilities. The margin of error for this estimate is 4.6 percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly 68% of all mall customers are satisfied with the facilities."},{"key":"B","text":"Between 63.4% and 72.6% of the sampled customers are satisfied with the facilities."},{"key":"C","text":"It is plausible that between 63.4% and 72.6% of all mall customers are satisfied with the facilities."},{"key":"D","text":"If another sample is taken, exactly 68% of those customers will also be satisfied."}]$lyceon_json$::jsonb, 'C', NULL, E'A margin of error defines a confidence interval around the sample statistic that provides a plausible range for the population parameter. Adding and subtracting 4.6 from 68 gives the interval 63.4% to 72.6% for all mall customers. The answer stating exactly 68% treats the sample statistic as the exact population value, ignoring sampling variability. The answer referring to the sampled customers applies the interval to the sample rather than the population. The answer predicting the next sample will yield exactly 68% confuses a point estimate with a guaranteed replication.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TTVQ4A', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'What is the minimum value of the function $g(x) = |x - 4| + 2$?', NULL, $lyceon_json$[{"key":"A","text":"$-2$"},{"key":"B","text":"$0$"},{"key":"C","text":"$2$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'C', NULL, E'The absolute value expression $|x - 4|$ is always greater than or equal to $0$, and it equals $0$ when $x = 4$. Therefore the minimum value of $g(x) = |x - 4| + 2$ is $0 + 2 = 2$, achieved at $x = 4$. The distractor $-2$ results from incorrectly subtracting the constant instead of adding it. The distractor $0$ comes from recognizing that absolute value has a minimum of $0$ but ignoring the vertical shift of $+2$. The distractor $4$ confuses the $x$-value where the minimum occurs with the minimum value of the function itself.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U4JD3I', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'Two chords \\(\\overline{AC}\\) and \\(\\overline{BD}\\) intersect inside a circle at point \\(E\\). If \\(AE = 6\\), \\(EC = 8\\), and \\(BE = 4\\), what is the length of \\(ED\\)?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '12', ARRAY['12'], E'By the intersecting chords theorem (power of a point), when two chords intersect inside a circle, the products of their segments are equal: \\(AE \\cdot EC = BE \\cdot ED\\). Substituting: \\(6 \\cdot 8 = 4 \\cdot ED\\), so \\(48 = 4 \\cdot ED\\), giving \\(ED = 12\\). A common error is adding the segments (\\(6 + 8 - 4 = 10\\)) instead of using the multiplicative relationship. Another error is setting up an incorrect proportion \\(\\frac{AE}{BE} = \\frac{EC}{ED}\\), yielding \\(ED = \\frac{16}{3}\\).', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ULELZP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A laptop originally priced at \\$800 is on sale for 15\\% off. What is the sale price of the laptop?', NULL, $lyceon_json$[{"key":"A","text":"\\$120"},{"key":"B","text":"\\$680"},{"key":"C","text":"\\$720"},{"key":"D","text":"\\$785"}]$lyceon_json$::jsonb, 'B', NULL, E'The discount is 15\\% of \\$800 = 0.15 \\times 800 = \\$120. The sale price is \\$800 - \\$120 = \\$680. The distractor \\$120 is the discount amount itself, not the sale price, resulting from misreading the question as asking for the discount. The distractor \\$720 results from computing a 10\\% discount (\\$80) instead of 15\\%. The distractor \\$785 results from subtracting 15 dollars instead of computing 15\\% of the price.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ULNZW1', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'A line passes through the points $(2, 7)$ and $(6, 15)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'First, calculate the slope: $m = \\frac{15 - 7}{6 - 2} = \\frac{8}{4} = 2$. Using the point $(2, 7)$ and the slope-intercept form $y = mx + b$: $7 = 2(2) + b$, so $7 = 4 + b$ and $b = 3$. The $y$-intercept is $3$. A common error is computing the slope as $\\frac{6 - 2}{15 - 7} = \\frac{1}{2}$ by inverting the rise and run, which leads to a different intercept. Another error is using the $x$-coordinate of one point as the answer without computing the intercept.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VOX7JI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A company records the commute times, in minutes, of 20 employees. The data set has a mean of 34 minutes and a median of 30 minutes. When one employee who commutes 120 minutes is removed from the data set, which of the following must be true?', NULL, $lyceon_json$[{"key":"A","text":"Both the mean and the median decrease."},{"key":"B","text":"The mean decreases, but the median may or may not change."},{"key":"C","text":"The median decreases, but the mean may or may not change."},{"key":"D","text":"Neither the mean nor the median changes."}]$lyceon_json$::jsonb, 'B', NULL, E'Removing the value 120 will decrease the mean because the new sum is 20(34) - 120 = 560, and the new mean is \\frac{560}{19} \\approx 29.47, which is less than 34. For the median, with 20 values the original median is the average of the 10th and 11th values in sorted order. After removing the largest value, there are 19 values and the new median is the 10th value. Since the removed value was the maximum, the positions of the 10th and 11th values from the original set are unchanged, so the median could remain the same or shift depending on whether those two values were equal. The distractor stating both must decrease incorrectly assumes removing an outlier always shifts the median. The distractor about the median decreasing while the mean may not change reverses which measure is sensitive to extreme values. The distractor about neither changing ignores that the mean is always affected by removing a value far above it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XFQ4DQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher models the relationship between hours of sunlight per day, x, and the weekly growth of a plant species in centimeters, y, using the line of best fit y = 0.85x - 2.4. A location that receives 8 hours of sunlight per day has an actual weekly growth of 5.0 cm. What is the residual for this observation?', NULL, $lyceon_json$[{"key":"A","text":"-0.60"},{"key":"B","text":"0.20"},{"key":"C","text":"0.60"},{"key":"D","text":"1.00"}]$lyceon_json$::jsonb, 'C', NULL, E'The predicted value is y = 0.85(8) - 2.4 = 6.80 - 2.4 = 4.40. The residual is actual minus predicted: 5.0 - 4.4 = 0.60. The distractor -0.60 results from computing predicted minus actual (4.4 - 5.0 = -0.6), reversing the subtraction order. The distractor 0.20 results from misreading the slope as 0.90, giving predicted = 0.90(8) - 2.4 = 7.2 - 2.4 = 4.8, and residual = 5.0 - 4.8 = 0.20. The distractor 1.00 results from misreading the slope as 0.80, giving predicted = 0.80(8) - 2.4 = 6.4 - 2.4 = 4.0, and residual = 5.0 - 4.0 = 1.0.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 95, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XW5G2N', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A chord of a circle is \\(8\\) units long and is \\(3\\) units from the center of the circle. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"\\(4\\)"},{"key":"B","text":"\\(5\\)"},{"key":"C","text":"\\(\\sqrt{7}\\)"},{"key":"D","text":"\\(7\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'A perpendicular from the center to a chord bisects the chord, creating a right triangle with legs equal to half the chord length (\\(4\\)) and the distance from the center (\\(3\\)). The hypotenuse is the radius: \\(r = \\sqrt{4^2 + 3^2} = \\sqrt{16 + 9} = \\sqrt{25} = 5\\). The value \\(4\\) uses only the half-chord length without applying the Pythagorean theorem. The value \\(\\sqrt{7}\\) results from subtracting \\(\\sqrt{16 - 9}\\) instead of adding under the radical. The value \\(7\\) results from adding \\(4 + 3\\) directly rather than using the Pythagorean theorem.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y3XXD8', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'A basketball player has scored a total of 84 points in her first 5 games this season. She wants her average points per game to be greater than 18 after 7 games. What is the minimum whole number of total points she must score in her next 2 games combined to achieve this goal?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '43', ARRAY['43'], E'After 7 games, the player''s average must be greater than 18, so $\\frac{84 + p}{7} > 18$, where $p$ is the total points scored in the next 2 games. Multiplying both sides by 7 gives $84 + p > 126$, so $p > 42$. Since points are whole numbers, the minimum value of $p$ that satisfies the strict inequality is 43. A common error is solving $p \\geq 42$ and reporting 42, which would give an average of exactly 18, not greater than 18. Another error is dividing by 5 instead of 7 when computing the required average, or forgetting to subtract the 84 points already scored.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YEVX2T', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'What is the range of the function $h(x) = -3(2)^{x-1} + 12$?', NULL, $lyceon_json$[{"key":"A","text":"All real numbers"},{"key":"B","text":"$h(x) > 12$"},{"key":"C","text":"$h(x) < 12$"},{"key":"D","text":"$h(x) > 0$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since $2^{x-1} > 0$ for all real $x$, the term $-3(2)^{x-1}$ is always negative. Thus $h(x) = -3(2)^{x-1} + 12 < 0 + 12 = 12$ for all $x$. As $x \\to -\\infty$, $2^{x-1} \\to 0$, so $h(x) \\to 12$ from below but never equals $12$. As $x \\to \\infty$, $2^{x-1} \\to \\infty$, so $h(x) \\to -\\infty$. The range is all values less than $12$. The distractor stating all real numbers incorrectly assumes an exponential function has no range restriction. The distractor $h(x) > 12$ reverses the inequality, ignoring that the negative coefficient reflects the exponential below the asymptote. The distractor $h(x) > 0$ incorrectly assumes the function stays positive, overlooking that $h(x)$ decreases without bound as $x$ increases.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z0XOR8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'From a point \\(P\\) outside a circle, a tangent segment \\(\\overline{PT}\\) has length \\(8\\), and a secant from \\(P\\) passes through the circle, intersecting it at points \\(A\\) and \\(B\\) (with \\(A\\) closer to \\(P\\)). If \\(PA = 4\\), what is the length of \\(PB\\)?', NULL, $lyceon_json$[{"key":"A","text":"\\(12\\)"},{"key":"B","text":"\\(16\\)"},{"key":"C","text":"\\(20\\)"},{"key":"D","text":"\\(32\\)"}]$lyceon_json$::jsonb, 'B', NULL, E'By the tangent-secant theorem, \\(PT^2 = PA \\cdot PB\\). Substituting: \\(64 = 4 \\cdot PB\\), so \\(PB = 16\\). The value \\(12\\) results from adding \\(8 + 4 = 12\\) instead of using the multiplicative power-of-a-point relationship. The value \\(20\\) results from setting \\(PT^2 = PA + PB\\) and solving \\(64 = 4 + PB\\), treating the relationship as additive subtraction from the square. The value \\(32\\) results from computing \\(\\frac{PT^2}{PA} \\cdot 2 = \\frac{64}{4} \\cdot 2\\), erroneously doubling the quotient.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZZQZG0', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $(2x + 3)^2 - (2x - 3)^2$?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$12x$"},{"key":"C","text":"$24x$"},{"key":"D","text":"$8x^2 + 18$"}]$lyceon_json$::jsonb, 'C', NULL, E'Using the difference of squares identity $a^2 - b^2 = (a + b)(a - b)$ with $a = 2x + 3$ and $b = 2x - 3$: $(2x + 3 + 2x - 3)(2x + 3 - 2x + 3) = (4x)(6) = 24x$. The distractor $0$ results from incorrectly assuming the two squared terms cancel entirely. The distractor $12x$ comes from computing only one of the two cross terms when expanding each square, yielding half the correct result. The distractor $8x^2 + 18$ results from adding the expansions instead of subtracting, obtaining $(4x^2 + 12x + 9) + (4x^2 - 12x + 9)$ rather than the correct subtraction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
