INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21O9UP5', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'For thousands of years, Indigenous Australians have used controlled, low-intensity burns to manage the landscape, a practice now termed "cultural burning." Unlike the high-intensity wildfires that devastate forests, cultural burns move slowly across the ground, clearing dry underbrush and leaf litter while leaving mature trees unharmed. These burns also promote the germination of native grasses and tubers that serve as food sources. Recently, Australian fire agencies have begun collaborating with Indigenous communities to integrate cultural burning into modern wildfire prevention strategies, recognizing that traditional ecological knowledge offers practical solutions to the growing threat of catastrophic bushfires.', $lyceon_json$[{"key":"A","text":"Indigenous Australian cultural burning is a long-standing land management practice now being incorporated into modern wildfire prevention efforts."},{"key":"B","text":"Australian fire agencies have replaced all conventional firefighting methods with Indigenous cultural burning techniques."},{"key":"C","text":"Cultural burning is primarily used to promote the growth of native food sources rather than to prevent wildfires."},{"key":"D","text":"High-intensity wildfires and cultural burns produce identical ecological outcomes but differ in their speed of progression."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how Indigenous Australians have long used cultural burning for land management and how modern fire agencies are now integrating this practice. The correct choice captures both the historical practice and its modern adoption. The option claiming agencies have replaced all conventional methods overstates the passage, which says they are collaborating, not replacing. The option focusing on food sources misidentifies a supporting detail as the main idea. The option equating wildfire and cultural burn outcomes contradicts the passage, which explicitly contrasts their effects.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21W9KTB', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Marine biologist Dr. Elena Vasquez has devoted her career to studying the migratory patterns of leatherback sea turtles across the Pacific Ocean. Using satellite tracking devices secured to the shells of nesting females on beaches in Papua New ______ Vasquez and her colleagues have mapped migration routes spanning over ten thousand kilometers. Their data reveal that these turtles navigate using a combination of Earth''s magnetic field and ocean current patterns to locate feeding grounds where jellyfish congregate in dense concentrations near the surface.', $lyceon_json$[{"key":"A","text":"Guinea. Vasquez"},{"key":"B","text":"Guinea, Vasquez"},{"key":"C","text":"Guinea; Vasquez"},{"key":"D","text":"Guinea Vasquez"}]$lyceon_json$::jsonb, 'B', NULL, E'The phrase beginning with "Using satellite tracking devices" is a participial phrase that modifies "Vasquez and her colleagues." An introductory participial phrase must be followed by a comma before the main clause begins. Placing a period after "Guinea" would turn the participial phrase into a sentence fragment, since it lacks a subject and finite verb. A semicolon after "Guinea" would similarly create a fragment on the left side, because a semicolon requires an independent clause on each side. Omitting all punctuation after "Guinea" produces a run-on that fuses the introductory phrase into the main clause without the required separation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW246K7G7', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the passage?', E'In 1971, the economist Herbert Simon warned that a wealth of information creates a poverty of attention. His observation has acquired new urgency in the digital age, where platforms compete not for consumers'' money but for their time. Critics of the attention economy argue that this competition degrades public discourse: when revenue depends on engagement, sensationalism displaces substance. Defenders counter that the same mechanisms democratize access to knowledge, enabling anyone with an internet connection to reach a global audience. What neither side disputes is that attention has become a scarce resource whose allocation carries profound social consequences.', $lyceon_json$[{"key":"A","text":"It summarizes a historical debate and demonstrates that one side has been vindicated by recent evidence."},{"key":"B","text":"It defines a technical term and provides a series of examples illustrating its practical applications."},{"key":"C","text":"It describes a problem, evaluates several proposed solutions, and recommends the most promising one."},{"key":"D","text":"It introduces a concept, presents opposing perspectives on that concept, and identifies a point of agreement between them."}]$lyceon_json$::jsonb, 'D', NULL, E'The passage opens by introducing Herbert Simon''s concept of attention scarcity, then presents critics who believe the attention economy degrades discourse and defenders who argue it democratizes knowledge, and concludes by noting that both sides agree attention is a consequential scarce resource. The option describing a concept introduced with opposing perspectives and a shared point of agreement captures this three-part structure precisely. The option about vindicating one side of a historical debate is incorrect because the passage explicitly avoids taking sides or declaring a winner. The option about defining a technical term with practical examples is incorrect because the passage presents a debate between perspectives rather than illustrating applications. The option about describing a problem and recommending a solution is incorrect because the passage neither proposes solutions nor endorses a recommendation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24WB8WO', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Master ceramicist Hiroshi Yamamoto, whose delicate porcelain vases are displayed in galleries across three continents, ______ a centuries-old Japanese firing technique that involves heating clay at temperatures exceeding two thousand degrees Fahrenheit. This extreme heat, which would destroy most conventional commercial glazes, actually produces the luminous crystalline surfaces for which Yamamoto''s vessels have become internationally celebrated. Each piece requires approximately six weeks of meticulous preparation before it enters the kiln for the final firing.', $lyceon_json$[{"key":"A","text":"employ"},{"key":"B","text":"employs"},{"key":"C","text":"are employing"},{"key":"D","text":"have employed"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the verb is "Master ceramicist Hiroshi Yamamoto," which is singular. The nonrestrictive clause "whose delicate porcelain vases are displayed in galleries across three continents" is set off by commas and does not change the subject. A singular subject requires the singular verb form "employs." The bare form "employ" is plural and does not agree with the singular subject. "Are employing" uses a plural auxiliary verb, also failing to agree with the singular subject. "Have employed" likewise uses a plural auxiliary and additionally shifts to present perfect tense, which is inconsistent with the passage''s use of simple present to describe Yamamoto''s ongoing practice.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27B47OY', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Computational linguist Dr. Yuki Tanaka has developed a machine learning model capable of identifying the geographic origins of undated medieval manuscripts based on microscopic variations in handwriting. The model was trained on a corpus of over fifty thousand digitized ______ which had been painstakingly cataloged and annotated by paleography specialists working across twelve European university archives over the past two decades. Preliminary trials indicate that the model can pinpoint a manuscript''s region of origin with greater precision than even the most experienced human analysts.', $lyceon_json$[{"key":"A","text":"documents, which"},{"key":"B","text":"documents; which"},{"key":"C","text":"documents. Which"},{"key":"D","text":"documents which"}]$lyceon_json$::jsonb, 'A', NULL, E'The clause "which had been painstakingly cataloged and annotated by paleography specialists" is a nonrestrictive relative clause providing additional information about the entire corpus of fifty thousand digitized documents—it does not restrict which documents are meant. In Standard English, a nonrestrictive "which" clause must be preceded by a comma. Placing a semicolon before "which" would require an independent clause on each side, but "which had been painstakingly cataloged..." is a dependent relative clause, not an independent clause. A period before "Which" would create a sentence fragment for the same reason. Omitting the comma entirely would make the clause appear restrictive, implying that only some documents in the corpus had been cataloged—contradicting the passage''s meaning that all fifty thousand documents received this treatment.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW289KJEC', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the passage?', E'Mathematicians have discovered that the centuries-old art of origami obeys a set of precise geometric axioms. In 1989, Humiaki Huzita formalized six axioms describing every possible single fold of a sheet of paper, later supplemented by a seventh discovered by Koshiro Hatori. These axioms proved that paper folding can solve geometric problems that are impossible with a compass and straightedge alone, including the trisection of an arbitrary angle and the doubling of a cube. The result has attracted the attention of engineers, who now apply origami principles to design deployable solar panels, medical stents, and space telescopes.', $lyceon_json$[{"key":"A","text":"It contrasts two competing approaches to a mathematical problem."},{"key":"B","text":"It proposes a hypothesis and then provides experimental evidence to test that hypothesis."},{"key":"C","text":"It presents a theoretical framework and then describes its practical applications."},{"key":"D","text":"It chronicles the career of a single researcher and evaluates that researcher's legacy."}]$lyceon_json$::jsonb, 'C', NULL, E'The passage first establishes the theoretical foundation—origami''s geometric axioms formalized by Huzita and Hatori—and then shifts to describing how engineers apply these principles to design real-world objects such as solar panels, stents, and telescopes. The option identifying a theoretical framework followed by practical applications accurately describes this two-part structure. The option about contrasting competing approaches is incorrect because the passage presents a single unified framework, not two rival methods. The option about proposing and testing a hypothesis is incorrect because the passage reports established axioms and their applications, not an experimental investigation. The option about chronicling a researcher''s career is incorrect because while Huzita is mentioned, the passage does not detail his career or evaluate his legacy.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AVP8PZ', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Glaciologists have long relied on ice cores drilled from polar ice sheets to reconstruct past climate conditions. These cylindrical samples preserve trapped air bubbles that contain atmospheric gases from thousands of years ago, allowing scientists to measure historical concentrations of carbon dioxide and methane. __________ ice cores from Greenland and Antarctica have provided some of the most compelling evidence that current greenhouse gas levels are unprecedented in at least 800,000 years of Earth''s history.', $lyceon_json$[{"key":"A","text":"In fact,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"In contrast,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence following the blank elaborates on and reinforces the claim that ice cores allow scientists to study past atmospheric conditions, presenting a specific and emphatic result of that research. "In fact," correctly signals this intensifying, supportive relationship. "Nevertheless," incorrectly introduces a concession or contrast, but the final sentence does not contradict the preceding information. "In contrast," wrongly implies the final sentence presents an opposing idea, when it actually extends the same line of reasoning. "Meanwhile," incorrectly suggests two simultaneous but unrelated events, whereas the final sentence is a direct consequence of the research described.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BM1Q28', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The urban planners who redesigned Copenhagen''s cycling infrastructure in 2012 ______ widely credited with transforming the city''s commuting culture. Since the network of protected bike lanes was expanded, the share of residents who commute by bicycle has risen from thirty-six to nearly fifty percent. Transportation analysts from other European capitals now regularly visit Copenhagen to study how its integrated system of dedicated lanes, traffic signals, and bicycle parking facilities encourages residents to choose cycling over driving for daily trips.', $lyceon_json$[{"key":"A","text":"is"},{"key":"B","text":"are"},{"key":"C","text":"was"},{"key":"D","text":"has been"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject is "The urban planners," a plural noun. The restrictive relative clause "who redesigned Copenhagen''s cycling infrastructure in 2012" modifies "planners" but does not change its number. A plural subject requires the plural verb "are." The singular "is" fails to agree with the plural subject. "Was" is singular past tense, failing on both number agreement and tense—the passage describes the planners'' current reputation, not a completed past state. "Has been" is singular present perfect, again failing to agree with the plural subject. The intervening clause between "planners" and the blank can mislead students into matching the verb to the nearest noun ("2012" or "infrastructure") rather than to the true subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CGKTAI', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the passage, "refined" most nearly means', E'In fermentation science, microorganisms such as yeast and bacteria transform sugars into acids, gases, or alcohol under anaerobic conditions. This ancient process, once regarded as mere spoilage, has been harnessed by cultures worldwide for millennia to preserve food and enhance flavor. Modern biotechnologists have refined these techniques, exploiting specific microbial strains to yield consistent results in industrial production. The precision now achievable in fermentation stands in stark contrast to the serendipitous discoveries that originally revealed the process''s potential.', $lyceon_json$[{"key":"A","text":"documented"},{"key":"B","text":"improved"},{"key":"C","text":"abandoned"},{"key":"D","text":"obscured"}]$lyceon_json$::jsonb, 'B', NULL, E'In this context, "refined" means improved or perfected through careful modification. The passage contrasts early serendipitous discoveries with the precision modern biotechnologists have achieved, indicating the techniques were made better over time. "Improved" captures this meaning of enhancement and perfection. "Documented" means recorded or cataloged, which describes preserving information rather than enhancing a process. "Abandoned" means gave up or ceased using, which is the opposite of the continued development described. "Obscured" means made unclear or hidden, which contradicts the increased precision the passage attributes to modern fermentation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DMWCL9', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the passage, "attenuate" most nearly means', E'Acoustic ecologists study how sound shapes the relationship between organisms and their environments. In undisturbed habitats, species partition the available acoustic spectrum, each occupying a distinct frequency band to communicate without interference. Human-generated noise, however, can occlude these channels, forcing animals to alter their vocalizations or abandon territories altogether. Researchers have found that even moderate noise pollution can attenuate the diversity of bird song in affected areas, as species unable to adapt to the altered soundscape gradually withdraw.', $lyceon_json$[{"key":"A","text":"diminish"},{"key":"B","text":"sustain"},{"key":"C","text":"amplify"},{"key":"D","text":"catalog"}]$lyceon_json$::jsonb, 'A', NULL, E'In this context, "attenuate" means to reduce or diminish in force, effect, or degree. The passage describes species withdrawing from areas affected by noise pollution, indicating that the diversity of bird song is being reduced. "Diminish" captures this meaning of gradual reduction. "Sustain" means to maintain at a constant level, which contradicts the passage''s description of species withdrawing and diversity declining. "Amplify" means to increase or make louder, which is the opposite of the reduction described in the passage. "Catalog" means to systematically list or record, which describes an act of documentation rather than the ecological decline the passage is presenting.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DTOHXW', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the passage?', E'Before the invention of mechanical clocks in medieval Europe, civilizations relied on natural phenomena to measure the passage of time. Ancient Egyptians observed the movement of shadows cast by obelisks, creating rudimentary sundials as early as 1500 BCE. The Greeks later developed water clocks, or clepsydrae, which measured time by the regulated flow of water from one vessel to another. Each of these innovations represented an attempt to impose order on the continuous flow of experience by dividing it into discrete, measurable units.', $lyceon_json$[{"key":"A","text":"To argue that ancient timekeeping methods were more accurate than modern ones"},{"key":"B","text":"To trace a sequence of early innovations in time measurement"},{"key":"C","text":"To explain why mechanical clocks eventually replaced earlier devices"},{"key":"D","text":"To compare the overall scientific achievements of Egyptian and Greek civilizations"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage chronologically describes two early timekeeping innovations—Egyptian sundials and Greek water clocks—presenting them as a sequence of attempts to measure time using natural phenomena. The option describing a traced sequence of early innovations accurately captures this structure. The option claiming the passage argues ancient methods were more accurate than modern ones misrepresents the passage, which makes no such comparative claim about accuracy. The option about explaining why mechanical clocks replaced earlier devices misreads the passage; mechanical clocks are mentioned only as temporal context, not explained. The option about comparing overall scientific achievements of two civilizations overstates the passage''s scope, which is limited to timekeeping rather than broad scientific comparison.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 55, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DYSNWW', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'The ancient Greek philosopher Pythagoras is credited with discovering that musical intervals perceived as consonant—such as the octave, perfect fifth, and perfect fourth—correspond to simple whole-number frequency ratios (2:1, 3:2, and 4:3 respectively). This mathematical framework dominated Western music theory for centuries. However, the tuning system derived from stacking perfect fifths, known as Pythagorean tuning, produces intervals that deviate slightly from the ratios needed to divide an octave into twelve equal steps. These deviations, called the Pythagorean comma, meant that keyboards tuned in this system could play in some keys beautifully but produced noticeably dissonant chords in others. The eventual adoption of equal temperament, which distributes the comma equally across all twelve intervals, therefore required musicians to ________', $lyceon_json$[{"key":"A","text":"accept slight impurities in every interval in exchange for the ability to play equally well in all keys."},{"key":"B","text":"abandon the mathematical basis of music theory in favor of purely subjective aesthetic judgments."},{"key":"C","text":"restrict their compositions to the small number of keys that Pythagorean tuning rendered consonant."},{"key":"D","text":"develop instruments capable of producing the exact whole-number frequency ratios Pythagoras described."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage explains that equal temperament distributes the Pythagorean comma across all twelve intervals, meaning no interval is perfectly pure but all keys are equally usable. The logical completion is that musicians accepted slight impurity in every interval for universal key flexibility. The option about abandoning mathematical foundations overstates the compromise; equal temperament is itself a mathematical system, not a rejection of mathematics. The option about restricting compositions to certain keys describes the problem Pythagorean tuning created, not the solution equal temperament provided. The option about developing instruments for exact ratios contradicts the passage''s point that equal temperament moves away from exact whole-number ratios.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ELLMZG', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The history of cartography reveals that maps have never been purely objective representations of geography. Medieval European mappae mundi placed Jerusalem at the center of the world, reflecting theological priorities rather than geographic accuracy. Chinese maps of the same period oriented south at the top, following cosmological conventions. Even modern satellite-derived maps involve choices about projection, scale, and labeling that emphasize certain features while obscuring others. Cartographic historians therefore conclude that all maps, regardless of their technical sophistication, ________', $lyceon_json$[{"key":"A","text":"are shaped by the cultural values and purposes of their makers."},{"key":"B","text":"have become less accurate over time as cultural biases have increased."},{"key":"C","text":"should be replaced by satellite imagery to eliminate subjective distortions."},{"key":"D","text":"are primarily useful as historical artifacts rather than navigational tools."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage traces cultural influences on mapmaking from medieval to modern times, showing that even satellite-derived maps involve subjective choices. The logical conclusion is that all maps reflect their makers'' cultural values. The option claiming maps have become less accurate contradicts the passage, which shows cultural influence has been constant across eras, not increasing. The option recommending replacement by satellite imagery introduces a prescriptive claim the passage does not support and ignores the text''s point that satellite maps also involve choices. The option reducing maps to historical artifacts contradicts the passage''s discussion of modern maps still in use.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H3RKUS', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'The Sapir-Whorf hypothesis, which proposes that the language a person speaks shapes how that person perceives and categorizes the world, has undergone significant revision since its mid-twentieth-century formulation. The strong version—that language determines thought—has been largely abandoned after cross-cultural studies showed that speakers of languages lacking certain color terms can still distinguish those colors perceptually. However, a growing body of experimental evidence supports a weaker version: that linguistic categories influence habitual patterns of attention and memory without rigidly constraining perception. For instance, speakers of languages with grammatical gender tend to associate gendered attributes with inanimate objects more readily than speakers of genderless languages, suggesting a subtle but measurable effect.', $lyceon_json$[{"key":"A","text":"While the strong claim that language determines thought has been discredited, research increasingly supports the view that language exerts a subtler influence on habitual cognition."},{"key":"B","text":"Cross-cultural studies have definitively disproven the Sapir-Whorf hypothesis by showing that perception operates independently of linguistic categories."},{"key":"C","text":"Experimental evidence has confirmed the strong version of the Sapir-Whorf hypothesis by demonstrating that grammatical gender shapes speakers' perceptions of objects."},{"key":"D","text":"The Sapir-Whorf hypothesis remains as controversial today as it was in the mid-twentieth century, with no consensus among researchers about its validity."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage traces the hypothesis''s evolution: the strong version was abandoned, but a weaker version finds growing experimental support. The correct choice accurately captures this nuanced trajectory. The option stating cross-cultural studies definitively disproved the entire hypothesis misreads the passage, which says those studies undermined only the strong version while the weaker version gained support. The option claiming the strong version was confirmed confuses the weak and strong versions; the gendered-attributes example supports the weak version. The option describing ongoing controversy mischaracterizes the passage, which presents a shift toward consensus on the weaker formulation rather than unresolved debate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H5NVYN', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'Johannes Gutenberg''s invention of the movable-type printing press around 1440 is often credited with democratizing knowledge in Europe, but the technology''s impact was neither immediate nor uniform. In its first decades, printed books were expensive luxury items accessible primarily to clergy and wealthy merchants. Only after innovations in papermaking, ink formulation, and press design reduced production costs did printed material reach broader audiences. Moreover, high illiteracy rates meant that the press''s transformative potential depended on parallel expansions in education. The printing revolution, scholars now argue, was less a single event than a cascade of interdependent social and technological changes unfolding over more than a century.', $lyceon_json$[{"key":"A","text":"The printing press was less transformative than historians have traditionally believed because most Europeans remained illiterate throughout the fifteenth century."},{"key":"B","text":"The impact of the printing press resulted from a gradual convergence of technological improvements and social changes rather than from the invention alone."},{"key":"C","text":"Gutenberg's printing press succeeded primarily because concurrent advances in papermaking made books affordable to the general public."},{"key":"D","text":"Scholars disagree about whether Gutenberg deserves credit for inventing the movable-type printing press."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage emphasizes that the printing press''s transformative effects depended on multiple interdependent changes over more than a century. The correct choice captures this idea of gradual, convergent change. The option about the press being less transformative overstates the passage''s argument; the text says the transformation was gradual, not that it was insignificant. The option crediting papermaking alone isolates one factor from several the passage names. The option about scholarly disagreement over Gutenberg''s credit introduces a debate not present in the text.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HN5E3R', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Bioluminescent fungi, which emit a soft green glow from their fruiting bodies or mycelium, have puzzled biologists because light production requires metabolic energy yet confers no immediately obvious reproductive advantage. One hypothesis proposes that the glow attracts nocturnal insects that then disperse the fungi''s spores, analogous to how flowering plants attract pollinators. Supporting this idea, researchers found that artificial models of luminous mushrooms placed in Brazilian forests attracted significantly more insects than non-luminous controls. However, not all bioluminescent fungal species produce spore-bearing structures that would benefit from insect visitation, which suggests that ________', $lyceon_json$[{"key":"A","text":"bioluminescence in fungi may serve different ecological functions across species rather than a single universal purpose."},{"key":"B","text":"the insect-attraction hypothesis has been conclusively disproven by the existence of species lacking spore-bearing structures."},{"key":"C","text":"metabolic energy spent on bioluminescence is always offset by increased spore dispersal efficiency in luminous fungi."},{"key":"D","text":"bioluminescent fungi evolved their glow exclusively as a byproduct of chemical reactions unrelated to ecological function."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents evidence supporting the insect-attraction hypothesis for some species but notes that other bioluminescent fungi lack the structures that would benefit from insect visits. The logical inference is that bioluminescence may serve different functions in different species. The option claiming the hypothesis is conclusively disproven overstates the evidence; the passage merely notes an exception, not a refutation. The option asserting that energy costs are always offset contradicts the passage''s observation that some species would not benefit from insect visitation. The option attributing bioluminescence exclusively to a chemical byproduct goes beyond the evidence, which supports ecological function for at least some species.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2L6ZNOJ', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Soil microbiome researchers have discovered that mycorrhizal fungal networks facilitate nutrient exchange between plants of different species, effectively redistributing phosphorus and nitrogen from resource-rich individuals to resource-poor neighbors. Some ecologists have argued that these networks demonstrate a form of cooperative resource sharing that challenges traditional models of interspecific competition. __________ other researchers caution that what appears cooperative may instead reflect parasitic dynamics, since the fungi extract carbon from host plants in return for the nutrients they deliver, and the net benefit to any given plant depends on context-specific variables.', $lyceon_json$[{"key":"A","text":"By contrast,"},{"key":"B","text":"Similarly,"},{"key":"C","text":"In addition,"},{"key":"D","text":"That is,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents one group of ecologists who see mycorrhizal networks as cooperative, then the sentence after the blank introduces a competing interpretation from other researchers who argue the dynamics may be parasitic. "By contrast," correctly signals this shift to an opposing scientific viewpoint. "Similarly," incorrectly implies the cautionary researchers agree with the cooperative interpretation, when they are challenging it. "In addition," wrongly suggests the parasitic-dynamics argument merely supplements the cooperative interpretation, but the two views are in tension, not additive. "That is," incorrectly implies the final sentence restates or clarifies the cooperative argument in different words, when it actually introduces a fundamentally different explanatory framework.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2L7RDAT', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When architectural restorers began work on the fifteenth-century cathedral in Rouen, France, they discovered that previous repair campaigns had inadvertently weakened the building''s flying buttresses. The original medieval masons ______ limestone quarried from nearby deposits along the Seine, but nineteenth-century restorers had substituted a softer imported sandstone that absorbed moisture and gradually crumbled under the structural loads it was designed to bear. The current restoration team has returned to sourcing stone that matches the original material in both mineral composition and load-bearing capacity.', $lyceon_json$[{"key":"A","text":"had used"},{"key":"B","text":"have used"},{"key":"C","text":"would use"},{"key":"D","text":"used"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes three distinct time layers: the medieval masons'' original construction (most distant past), the nineteenth-century restorers'' substitution (intermediate past), and the current team''s work (present). The nineteenth-century action is expressed in the past perfect ("had substituted"), indicating it occurred before the restorers in the present narrative "discovered" the damage. The medieval masons'' action occurred even earlier—before the nineteenth-century substitution—and therefore also requires the past perfect "had used" to maintain the correct temporal sequence relative to the simple past "discovered." Present perfect "have used" implies a connection to the present, which is incorrect for medieval masons whose work ended centuries ago. The conditional "would use" implies a hypothetical or habitual action rather than a completed historical one. Simple past "used" would place the medieval action at the same temporal level as "discovered" and "began," collapsing the necessary distinction between the discovery and the far earlier construction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ME0PET', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Marine biologists studying microplastic pollution have hypothesized that filter-feeding organisms such as mussels and oysters are particularly vulnerable to microplastic ingestion because their feeding mechanism indiscriminately captures suspended particles from seawater. Unlike selective feeders that can detect and reject non-food items, filter feeders process large volumes of water and retain particles within a certain size range regardless of composition. The researchers predict that microplastic concentrations in filter-feeder tissues should correlate with ambient microplastic levels in surrounding waters and should exceed concentrations found in selective-feeding species inhabiting the same environment.', $lyceon_json$[{"key":"A","text":"Mussels collected from harbors with high microplastic concentrations contained significantly more microplastic particles per gram of tissue than fish species collected from the same harbors."},{"key":"B","text":"Microplastic pollution levels vary dramatically between coastal and open-ocean environments."},{"key":"C","text":"Some filter-feeding species have evolved mechanisms to expel indigestible particles after initial ingestion."},{"key":"D","text":"Selective-feeding fish species in heavily polluted waters show elevated levels of chemical contaminants absorbed through their gills."}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers predict that filter feeders should have higher microplastic concentrations than selective feeders in the same environment. The correct choice directly confirms this prediction by comparing mussels (filter feeders) to fish (selective feeders) in the same harbor. The option about variation between coastal and open-ocean environments addresses pollution distribution but does not compare filter feeders to selective feeders. The option about expelling indigestible particles would undermine, not support, the hypothesis. The option about chemical contaminants in fish concerns a different pollutant type and uptake pathway, not microplastic ingestion through feeding.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 55, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NR4KXC', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Which choice best states the relationship between the claim made by biomimicry advocates in Text 1 and Tanaka''s position in Text 2?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SFLBXM', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which quotation from a research study would most effectively support the underlined claim?', E'Epigenetics—the study of heritable changes in gene expression that occur without alterations to the DNA sequence itself—has challenged the traditional view that inherited traits are transmitted exclusively through genetic code. Researchers have demonstrated that environmental factors such as diet, stress, and toxin exposure can modify chemical tags on DNA, particularly methyl groups attached to cytosine bases, and that some of these modifications persist across generations. One especially provocative finding is that _the epigenetic effects of a parent''s experiences can influence offspring who were never directly exposed to the triggering environmental condition_. This transgenerational inheritance operates through mechanisms distinct from Mendelian genetics and has been documented in organisms ranging from plants to mammals.', $lyceon_json$[{"key":"A","text":"\"Male mice conditioned to associate a specific odor with mild foot shocks produced offspring that exhibited heightened sensitivity to the same odor despite never having encountered the stimulus or the conditioning procedure.\""},{"key":"B","text":"\"Mice fed a diet supplemented with methyl donors showed increased DNA methylation at the agouti gene locus, resulting in offspring with brown rather than yellow coat color when the supplement was administered during pregnancy.\""},{"key":"C","text":"\"Identical twins raised in different environments showed divergent DNA methylation patterns by age fifty, suggesting that life experience modifies epigenetic markers over an individual's lifetime.\""},{"key":"D","text":"\"Exposure to endocrine-disrupting chemicals during fetal development altered DNA methylation patterns in the exposed offspring, increasing their susceptibility to metabolic disorders in adulthood.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined claim states that parental experiences can affect offspring who were never exposed to the triggering condition. The correct choice directly illustrates this: fathers were conditioned, and their offspring—never exposed to the conditioning—showed heightened sensitivity. The option about methyl-donor diets during pregnancy describes a direct prenatal exposure, not transmission to unexposed offspring. The option about identical twins demonstrates that environment modifies epigenetic markers within an individual''s lifetime but says nothing about transmission to the next generation. The option about fetal chemical exposure describes effects on directly exposed offspring during development, not on offspring who were never exposed to the trigger.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TZ2A9E', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Documentary filmmaker Priya Anand spent three years following the construction of a controversial highway through a protected wetland in southern Louisiana. Although environmental advocacy groups had filed numerous lawsuits arguing that the project would irreparably damage the habitat of several endangered bird ______ the state transportation authority continued to approve new construction permits. Anand''s film juxtaposes testimony from displaced wildlife biologists with interviews of engineers defending the highway''s economic necessity for surrounding rural communities.', $lyceon_json$[{"key":"A","text":"species, the"},{"key":"B","text":"species; the"},{"key":"C","text":"species. The"},{"key":"D","text":"species the"}]$lyceon_json$::jsonb, 'A', NULL, E'The clause beginning with "Although" is a subordinate dependent clause that must be joined to the main clause ("the state transportation authority continued to approve new construction permits") with a comma. A semicolon after "species" would require an independent clause on each side, but "Although environmental advocacy groups had filed numerous lawsuits..." is not an independent clause—it begins with the subordinating conjunction "Although." A period after "species" would create a sentence fragment for the same reason: the "Although" clause cannot stand alone as a sentence. Omitting punctuation entirely fuses the dependent clause into the main clause without the required comma separation after an introductory subordinate clause.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UCQY8S', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Comparative mythologist Dr. Liora Friedman has argued that the flood narratives appearing independently in the mythologies of geographically isolated cultures ______ not from a single shared catastrophic event, as earlier scholars had proposed, but from the universal human experience of seasonal river inundation. Friedman''s analysis of over two hundred flood myths collected from societies spanning six continents reveals striking structural parallels that she attributes to common cognitive patterns governing how communities process collective trauma rather than to any historical contact between ancient civilizations.', $lyceon_json$[{"key":"A","text":"derives"},{"key":"B","text":"derive"},{"key":"C","text":"deriving"},{"key":"D","text":"has derived"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the clause is "the flood narratives," a plural noun. The participial phrase "appearing independently in the mythologies of geographically isolated cultures" modifies "narratives" but does not change its grammatical number. A plural subject requires the plural verb form "derive." The singular "derives" fails to agree with the plural subject—students may be misled by the intervening phrase, which places the singular noun "cultures" immediately before the blank. The participial form "deriving" would leave the clause without a finite verb, producing a fragment rather than a complete sentence within the "that" clause. The singular "has derived" fails on number agreement and also shifts the construction from a state (narratives derive from a source) to a completed action, which misrepresents the logical relationship the sentence describes.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 115, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UNTY4T', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the passage, "devise" most nearly means', E'Engineers studying biomimicry have long been captivated by the way certain organisms solve complex structural problems. The lotus leaf, for example, possesses a surface covered in microscopic wax crystals that repel water with remarkable efficiency. This self-cleaning property has inspired the development of coatings for buildings and vehicles. By emulating nature''s tested strategies, researchers hope to devise materials that are both more durable and more sustainable than their conventional counterparts.', $lyceon_json$[{"key":"A","text":"locate"},{"key":"B","text":"purchase"},{"key":"C","text":"create"},{"key":"D","text":"discard"}]$lyceon_json$::jsonb, 'C', NULL, E'In this context, "devise" means to invent or create something through careful thought. The passage describes researchers hoping to produce new materials inspired by nature. "Create" captures this meaning of bringing something new into existence. "Locate" means to find something that already exists, which contradicts the idea of developing new materials. "Purchase" means to buy, which has no connection to the inventive process described. "Discard" means to throw away or get rid of, which is the opposite of the productive activity the passage describes.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2USJNJN', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding, if true, would most directly weaken the claim made in the text?', E'Researchers tracking space debris in low Earth orbit have argued that the current rate of satellite launches, if sustained, will trigger a self-reinforcing cascade of collisions known as Kessler syndrome within the next fifty years. In this scenario, each collision generates fragments that increase the probability of further collisions, eventually rendering certain orbital bands unusable. The researchers base their projection on computational models incorporating current launch rates, satellite lifetimes, and the observed growth in trackable debris objects. They contend that voluntary deorbiting guidelines adopted by some satellite operators are insufficient to prevent this outcome and that binding international regulations are necessary.', $lyceon_json$[{"key":"A","text":"A new propulsion technology enables satellites to deorbit reliably within two years of mission completion, and major operators have begun adopting it at scale."},{"key":"B","text":"The number of countries launching satellites has increased by forty percent over the past decade."},{"key":"C","text":"Several recent near-miss events between defunct satellites have drawn increased media attention to the space debris problem."},{"key":"D","text":"Computational models of orbital debris have become significantly more accurate over the past decade due to improvements in radar tracking."}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers claim that voluntary deorbiting guidelines are insufficient and binding regulations are necessary to prevent Kessler syndrome. The correct choice weakens this claim by showing that a technological solution adopted voluntarily by operators could effectively reduce debris accumulation without binding regulations. The option about more countries launching satellites would strengthen the concern rather than weaken it. The option about near-miss events and media attention describes heightened awareness but does not address whether voluntary measures can work. The option about improved model accuracy supports the credibility of the models but does not counter the claim about the need for regulations.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VXS1V6', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief introduction to a community newsletter article about urban beekeeping. The student wants to emphasize the environmental benefits of urban beekeeping programs. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WRSI3F', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Recent advances in veterinary oncology have enabled the development of targeted immunotherapies for companion animals, treatments once available only to human patients. Early clinical trials in dogs with osteosarcoma have shown that monoclonal antibody therapies can shrink tumors and extend survival times by several months. __________ these veterinary trials also serve a translational purpose: because canine cancers share molecular pathways with their human counterparts, insights from treating dogs may accelerate the development of novel cancer therapies for people.', $lyceon_json$[{"key":"A","text":"On the other hand,"},{"key":"B","text":"Moreover,"},{"key":"C","text":"For this reason,"},{"key":"D","text":"In summary,"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage first establishes that targeted immunotherapies benefit companion animals, then the sentence after the blank introduces an additional, distinct benefit: these trials also aid human medicine. "Moreover," correctly signals that a second, layered advantage is being added to the first. "On the other hand," incorrectly implies a contrast, but the translational benefit does not oppose the veterinary benefit; it supplements it. "For this reason," wrongly suggests the translational purpose is caused by the tumor-shrinking results, when the passage actually presents a separate rationale grounded in shared molecular pathways. "In summary," incorrectly implies the final sentence is recapping prior information, but it introduces an entirely new dimension of the research''s significance.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XG1NV5', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'In theater set design, forced perspective is a technique in which scenic elements are constructed at progressively smaller scales to create the illusion of greater depth on a shallow stage. A hallway that appears to stretch thirty meters may occupy only five meters of actual stage space. __________ this technique demands exacting geometric calculations; even minor miscalculations in the scaling ratios can shatter the illusion for audience members seated at certain angles, making the set appear distorted rather than expansive.', $lyceon_json$[{"key":"A","text":"For instance,"},{"key":"B","text":"However,"},{"key":"C","text":"Consequently,"},{"key":"D","text":"Specifically,"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage first describes forced perspective as an effective illusion technique, then the sentence after the blank introduces a complication: the technique requires exacting calculations and can fail if executed improperly. "However," correctly signals this shift from a positive description to a qualification or drawback. "For instance," incorrectly suggests the final sentence provides an example of the illusion working, when it actually introduces a limitation. "Consequently," wrongly implies the difficulty is a direct result of the illusion being effective, but the passage is introducing a counterpoint, not a causal chain. "Specifically," incorrectly suggests the final sentence is narrowing or elaborating on the same idea, when it is actually shifting to a contrasting concern about the technique''s challenges.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
