INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YHEIMQ', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a report on the history of typography for a design class. The student wants to highlight how a specific technological development changed the accessibility of printed text. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Z7HHAV', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Paleoclimatologist Dr. Amara Osei has spent two decades reconstructing ancient atmospheric conditions by analyzing gas bubbles trapped deep within Antarctic ice cores. Because the ratio of oxygen isotopes preserved in these microscopic bubbles closely reflects the average atmospheric temperature at the time each layer of ice originally ______ Osei can estimate global temperature fluctuations for periods stretching back eight hundred thousand years. Her reconstructions reveal that the current pace of atmospheric warming is unmatched in the entire ice-core record, a finding that has intensified calls for more aggressive international climate policy.', $lyceon_json$[{"key":"A","text":"formed, Osei"},{"key":"B","text":"formed; Osei"},{"key":"C","text":"formed. Osei"},{"key":"D","text":"formed Osei"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence opens with the subordinating conjunction "Because," making everything from "Because" through "formed" a single dependent adverbial clause. When such a clause precedes the main clause, a comma must separate them. A semicolon after "formed" would be incorrect because a semicolon requires an independent clause on each side, and a "Because" clause is dependent. A period after "formed" would produce a sentence fragment beginning with "Because" that lacks a main clause to complete its meaning. Omitting all punctuation fuses the long dependent clause directly into the main clause without the required comma, creating an unpunctuated run-on. The difficulty lies in tracking the "Because" across a lengthy, internally complex clause containing a nested relative structure ("at the time each layer of ice originally formed"), which can mislead readers into treating the material before the blank as an independent clause.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 115, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-17"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-17","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
